 d=c['decode_telemetry'];ks=['system_cpu_pct_mean_median','process_cpu_pct_mean_median','GPU0_util_pct_mean_median','GPU1_util_pct_mean_median','GPU0_power_w_mean_median','GPU1_power_w_mean_median'];lines.append('| '+str(c['target_prompt_tokens'])+' | '+' | '.join(f'{d[k]:.1f}' for k in ks)+' |')
