for x in s['RTX5090_comparison']:lines.append(f'| {x["actual_prompt_target"]} | {x["RTX5090_TG_user_supplied"]:.1f} | {x["our_2x4090_TG_median"]:.1f} | {x["difference_pct"]:+.2f} |')
